function dir$m74(p){
  this.constructor(p);
}
dir$m74.prototype = new DirEvent();
dir$m74.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid();
  var exp = {
    tien_nt: ['*tien_nt', '[so_luong]*[he_so]*[gia_nt]'], // Cong thuc tung dong cua GRID
    gia: ['*gia', '[!ty_gia]*[gia_nt]'],
    tien: ['*tien', '[so_luong]*[he_so]*[gia]'],
    tien_tg: ['*tien', '[!ty_gia]*[tien_nt]'],

    t_so_luong: ['@t_so_luong', '[so_luong]'],
    t_tien_nt: ['@t_tien_nt', '[tien_nt]'],
    t_tien: ['@t_tien', '[tien]']
  }
  p.applyExpression(exp, g, false); //Ko can de quy tinh cong thuc

  g.FomulaApplied = {
    "so_luong":["t_so_luong","tien_nt","tien_tg","t_tien_nt","t_tien"],
    "he_so":["tien_nt","tien_tg","t_tien_nt","t_tien"],
    "gia_nt":["tien_nt","gia","tien_tg","t_tien_nt","t_tien"],
    "!ty_gia":["gia", "tien_tg", "t_tien"],
    "tien_nt":["tien_tg","t_tien_nt","t_tien"],
    "gia":["tien","t_tien"],
    "tien":["t_tien"]
  } //Gan lai valid của từng cột sẽ tính các công thức nào theo thứ tự.

  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 

  p.options.FCColumns = {FC: ['t_tien_nt'], BC: ['t_tien']};
  g.FCColumns = {FC: ['gia_nt', 'tien_nt'], BC: ['gia', 'tien']};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
  p.setFCHidden(oTG.fval());

  dir$m74DisabledMasterField(p, g);
  dir$m74HiddenColumnByType(p);
  dir$m74HiddenColumnByTran(p);
  dir$m74DisabledStatusByAction(p);
}

dir$m74.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
      var rows = dt.findRow("[so_luong] > [sl_ton]") //Ban chuan chi xu ly canh bao ton kho tuc thoi tren client
      if (p.valForm('status') != '0' && p.options.dataChanged && (p.valForm('ma_ngv') == 2 || p.valForm('ma_ngv') == 3) && rows.length) {
        $.question('$VoucherCurrentStockOverload', $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v)
            p.options.event.buttonDialogClick(id, false);
          else {
            p.tabActive("1");
            p.jCell(rows[0], 'so_luong', 0).focus();
          }
        });
        return false;
      }
      break;
    default:
      break;
  }
  return true;
}
dir$m74.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    default:
      break;
  }
  return true;
}

dir$m74.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c) {
    case 'ma_vt':
      p.grequest(g, 'Item', '', ['ma_vt', 'dvt', 'he_so', '!ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run) {
        p.calcValidExpression(g, 'he_so', r);
        dir$m74DisabledMasterField(p, g);
      }, r);
      break;
    case 'dvt':
      p.grequest(g, 'UOM', '', ['ma_vt', 'dvt', 'he_so', '!ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], function(pp, d, run) {
        p.calcValidExpression(g, 'he_so', r);
      }, r);
      break;
    case 'ma_khon':
      p.grequest(g, 'SiteN', '', ['ma_vt', 'dvt', 'he_so', 'ma_khon', 'ma_lo', 'ma_vi_trin', '!unit_id'], null, r);
      break;
    case 'ma_lo':
      if (p.options._lot_current_stock) p.grequest(g, 'Lot', '', ['ma_vt', 'dvt', 'he_so', '!ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], null, r);
      break;
    case 'ma_vi_tri':
      if (p.options._location_current_stock) p.grequest(g, 'Location', '', ['ma_vt', 'dvt', 'he_so', '!ma_kho', 'ma_lo', 'ma_vi_tri', '!unit_id'], null, r);
      break;
    default:
      break;
  }
}
dir$m74.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  if (cF == 'unit_id') p.valForm(['ma_kho', 'ten_kho'], ['', '']);
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$m74HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$m74HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kho':
      //p.setDisabled('unit_id', p.valForm('ma_kho').trim() != '');
      break;
	case 'ma_job':
		dir$m74LoadDataJob(p);
	break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$m74.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$m74DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$m74DisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_vt].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
  p.setDisabled('ma_ngv', dis);
  p.setDisabled('ma_kho', dis);
}
function dir$m74HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  p.setColumnAuth(0, ['px_dd', 'gia_nt', 'gia', 'tien_nt', 'tien'], v == 2);
  p.setColumnHidden(0, ['gia', 'tien'], nt == bc);
  p.setAuth(['t_tien_nt', 't_tien'], v == 2, true);
  p.setInvisible(['t_tien'], nt == bc);
}
function dir$m74HiddenColumnByTran(p){

}
function dir$m74DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}

function dir$m74LoadDataJob(p){
	var majob = p.valForm('ma_job');
	if(p.options.action == "NEW") {
		if ( majob != "" ) p.request('so_job', '',['ngay_ct','ma_job'])
		else p.valForm('so_job',"",true);
	}
}







